TreeNode insert(TreeNode node, int val) {
    if (node == null) return new TreeNode(val);  // an empty spot: the value lives here
    if (val < node.val) node.left = insert(node.left, val);
    else node.right = insert(node.right, val);   // equal values go right
    return node;
}

TreeNode buildBST(int[] values) {
    TreeNode root = null;
    for (int v : values) root = insert(root, v);
    return root;
}

TreeNode* insert(TreeNode* node, int val) {
    if (node == nullptr) return new TreeNode(val);   // an empty spot: the value lives here
    if (val < node->val) node->left = insert(node->left, val);
    else node->right = insert(node->right, val);     // equal values go right
    return node;
}

TreeNode* buildBST(vector<int>& values) {
    TreeNode* root = nullptr;
    for (int v : values) root = insert(root, v);
    return root;
}
